	pwm_clock_divider_rg_counter <= `BSV_ASSIGNMENT_DELAY 16'd0;
	pwm_clock_divider_rg_divisor <= `BSV_ASSIGNMENT_DELAY 16'd0;
      end
    else
      begin
        if (pwm_clock_divider_clk_EN)
	  pwm_clock_divider_clk <= `BSV_ASSIGNMENT_DELAY
	      pwm_clock_divider_clk_D_IN;
	if (pwm_clock_divider_rg_counter_EN)
	  pwm_clock_divider_rg_counter <= `BSV_ASSIGNMENT_DELAY
	      pwm_clock_divider_rg_counter_D_IN;
	if (pwm_clock_divider_rg_divisor_EN)
	  pwm_clock_divider_rg_divisor <= `BSV_ASSIGNMENT_DELAY
	      pwm_clock_divider_rg_divisor_D_IN;
      end
  end

  always@(posedge pwm_clock_divider_clock_selector_CLK_OUT)
  begin
    if (pwm_downreset_OUT_RST == `BSV_RESET_VALUE)
      begin
        pwm_pwm_output <= `BSV_ASSIGNMENT_DELAY 1'd0;
	pwm_rg_counter <= `BSV_ASSIGNMENT_DELAY 16'd0;
      end
    else
      begin
        if (pwm_pwm_output_EN)
	  pwm_pwm_output <= `BSV_ASSIGNMENT_DELAY pwm_pwm_output_D_IN;
	if (pwm_rg_counter_EN)
	  pwm_rg_counter <= `BSV_ASSIGNMENT_DELAY pwm_rg_counter_D_IN;
      end
  end

  // synopsys translate_off
  `ifdef BSV_NO_INITIAL_BLOCKS
  `else // not BSV_NO_INITIAL_BLOCKS
  initial
  begin
    pwm_clock_divider_clk = 1'h0;
    pwm_clock_divider_rg_counter = 16'hAAAA;
    pwm_clock_divider_rg_divisor = 16'hAAAA;
    pwm_clock_divisor = 16'hAAAA;
    pwm_clock_selector = 1'h0;
    pwm_continous_once = 1'h0;
    pwm_duty_cycle = 16'hAAAA;
    pwm_interrupt = 1'h0;
    pwm_period = 16'hAAAA;
    pwm_pwm_enable = 1'h0;
    pwm_pwm_output = 1'h0;
    pwm_pwm_output_enable = 1'h0;
    pwm_pwm_start = 1'h0;
    pwm_reset_counter = 1'h0;
    pwm_rg_counter = 16'hAAAA;
  end
  `endif // BSV_NO_INITIAL_BLOCKS
  // synopsys translate_on
endmodule  // mkpwm_e32

